<?php

namespace App\Actions;

use App\Models\Consultation;
use App\Models\Discharge;
use App\Models\Doctor;
use App\Models\LabOrder;
use App\Models\Patient;
use App\Models\Prescription;
use App\Models\Turn;
use App\Support\LabPresenter;

class BuildClinicalHistory
{
    /**
     * Build a unified clinical history for a patient.
     *
     * Returns a list of entries (consulta | receta | alta) ordered most-recent first.
     * Each entry carries a `mine` flag: true if it was generated by `$callerDoctor`
     * (always false when the viewer is not a doctor, e.g. from the patient profile).
     *
     * Rules:
     * - Each consultation note → `consulta` entry (with prescription/discharge from its turn).
     * - Each prescription on a turn that has NO consultation note → standalone `receta` entry.
     * - Each discharge on a turn that has NO consultation note → standalone `alta` entry.
     * Consultations with no turn (turn_id = null) are also included as `consulta` entries.
     *
     * @return list<array<string, mixed>>
     */
    public function handle(Patient $patient, ?Doctor $callerDoctor): array
    {
        $entries = collect();

        // 1. All consultations (including orphans with turn_id = null) → consulta entries
        $consultations = Consultation::with(['doctor.specialty', 'turn.prescription.items', 'turn.discharge'])
            ->where('patient_id', $patient->id)
            ->get();

        // Track turn IDs that have a consultation so we skip them in the turn pass
        $turnIdsWithConsultation = $consultations
            ->pluck('turn_id')
            ->filter()
            ->flip();

        foreach ($consultations as $c) {
            $mine = $c->doctor_id === $callerDoctor?->id;
            $entries->push($this->makeConsultaEntryFromConsultation($c, $mine));
        }

        // 2. Turns with NO consultation: check for standalone prescription / discharge
        $turns = Turn::with([
            'doctor.specialty',
            'prescription.items',
            'discharge',
        ])
            ->where('patient_id', $patient->id)
            ->whereNotIn('id', $turnIdsWithConsultation->keys()->all())
            ->get();

        foreach ($turns as $turn) {
            $mine = $turn->doctor_id === $callerDoctor?->id;

            if ($turn->prescription !== null) {
                $entries->push($this->makeRecetaEntry($turn, $turn->prescription, $mine));
            }

            if ($turn->discharge !== null) {
                $entries->push($this->makeAltaEntry($turn, $turn->discharge, $mine));
            }
        }

        // 3. Validated laboratory results
        $labOrders = LabOrder::with(['items.results', 'doctor.specialty'])
            ->where('patient_id', $patient->id)
            ->whereIn('status', ['validada', 'entregada'])
            ->get();
        $lab = app(LabPresenter::class);
        foreach ($labOrders as $order) {
            $entries->push([
                'type' => 'laboratorio',
                'date' => ($order->validated_at ?? $order->ordered_at)->toIso8601String(),
                'mine' => $order->doctor_id !== null && $order->doctor_id === $callerDoctor?->id,
                'doctor' => [
                    'id' => $order->doctor_id ?? 0,
                    'full_name' => $order->doctor_id !== null ? $order->doctor->name : ($order->external_doctor ?? 'Laboratorio'),
                    'specialty' => $order->doctor_id !== null ? $order->doctor->specialty->name : 'Laboratorio',
                ],
                'lab' => [
                    'number' => $order->number,
                    'tests' => $order->items->pluck('name')->all(),
                    'results' => $lab->flatResults($order),
                ],
            ]);
        }

        // Sort by date descending
        return $entries
            ->sortByDesc('date')
            ->values()
            ->all();
    }

    /** @return array<string, mixed> */
    private function makeConsultaEntryFromConsultation(Consultation $c, bool $mine): array
    {
        $discharge = $c->turn?->discharge;
        $prescription = $c->turn?->prescription;

        return [
            'type' => 'consulta',
            'date' => $c->consulted_at->toIso8601String(),
            'mine' => $mine,
            'doctor' => [
                'id' => $c->doctor->id,
                'full_name' => $c->doctor->name,
                'specialty' => $c->doctor->specialty->name,
            ],
            'motivo_consulta' => $c->motivo_consulta,
            'historia_enfermedad' => $c->historia_enfermedad,
            'examen_fisico' => $c->examen_fisico,
            'diagnosticos' => $c->diagnosticos,
            'plan_tratamiento' => $c->plan_tratamiento,
            'vitals' => [
                'peso' => $c->peso,
                'talla' => $c->talla,
                'temp' => $c->temp,
                'presion_arterial' => $c->presion_arterial,
                'frecuencia_cardiaca' => $c->frecuencia_cardiaca,
                'frecuencia_respiratoria' => $c->frecuencia_respiratoria,
                'saturacion_o2' => $c->saturacion_o2,
                'glucemia' => $c->glucemia,
            ],
            'discharge' => $discharge ? [
                'type' => $discharge->type,
                'destination' => $discharge->destination,
                'discharge_diagnosis' => $discharge->discharge_diagnosis,
                'discharged_at' => $discharge->discharged_at->toIso8601String(),
            ] : null,
            'prescription' => $prescription
                ? $this->formatPrescription($prescription)
                : null,
        ];
    }

    /** @return array<string, mixed> */
    private function makeRecetaEntry(Turn $turn, Prescription $p, bool $mine): array
    {
        return [
            'type' => 'receta',
            'date' => $p->prescribed_at->toIso8601String(),
            'mine' => $mine,
            'doctor' => [
                'id' => $turn->doctor->id,
                'full_name' => $turn->doctor->name,
                'specialty' => $turn->doctor->specialty->name,
            ],
            'prescription' => $this->formatPrescription($p),
        ];
    }

    /** @return array<string, mixed> */
    private function makeAltaEntry(Turn $turn, Discharge $d, bool $mine): array
    {
        return [
            'type' => 'alta',
            'date' => $d->discharged_at->toIso8601String(),
            'mine' => $mine,
            'doctor' => [
                'id' => $turn->doctor->id,
                'full_name' => $turn->doctor->name,
                'specialty' => $turn->doctor->specialty->name,
            ],
            'discharge' => [
                'type' => $d->type,
                'destination' => $d->destination,
                'discharge_diagnosis' => $d->discharge_diagnosis,
                'discharged_at' => $d->discharged_at->toIso8601String(),
            ],
        ];
    }

    /** @return array<string, mixed> */
    private function formatPrescription(Prescription $p): array
    {
        return [
            'id' => $p->id,
            'general_instructions' => $p->general_instructions,
            'prescribed_at' => $p->prescribed_at->toIso8601String(),
            'items' => $p->items->map(fn ($item) => [
                'id' => $item->id,
                'position' => $item->position,
                'medication' => $item->medication,
                'route' => $item->route,
                'dose' => $item->dose,
                'frequency' => $item->frequency,
                'duration_days' => $item->duration_days,
                'is_continuous' => $item->is_continuous,
                'quantity' => $item->quantity,
            ])->all(),
        ];
    }
}
